11	/**
12	 * The host's two fuel refusals as a question asked before dispatch: the planet must hold the flight's
13	 * deuterium ("Not enough resources on the planet") and the fleet's own tanks must carry it ("You don't
14	 * have sufficient storage capacity"). An errand that fails either is not sent; the STUCK rows measured
15	 * the same account retrying such a dispatch every few minutes.
16	 */
17	class FlightFuel
18	{
19	    public function affordable(PlayerService $player, PlanetService $origin, UnitCollection $fleet, Coordinate $target, float $speedPercent, int $holdingHours = 0): bool
20	    {
21	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
22	        $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $target, $holdingHours, $speedPercent);
23	
24	        return $fuel <= floor($origin->deuterium()->get()) && $fuel <= $fleet->getTotalFuelCapacity($player);
25	    }
26	}

