  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use Modules\AI\Enums\AiActionType;
  6	use Modules\AI\Enums\AiQueueActionReason;
  7	use Modules\AI\Enums\AiReceiptState;
  8	use Modules\AI\Models\AiActionReceipt;
  9	use Symfony\Component\Yaml\Yaml;
 10	
 11	/**
 12	 * What the host or the dispatch gate refused this account a moment ago.
 13	 *
 14	 * A refused dispatch is not a mission, so nothing the planners read recorded it and the same target or
 15	 * the same origin was offered again on the next login (measured 4 Oct 2026: one account tried one
 16	 * target 21 times in six hours). A player who was told "that planet is online" leaves it alone for a
 17	 * while; this is that memory, read from the receipts the gate already writes.
 18	 *
 19	 * The refusal cools what it blamed for as long as a launched mission cools its target, so a cooling
 20	 * shorter than the span DISPATCH_REFUSALS counts cannot let a repeat land inside it. How long that is
 21	 * lives in `resources/behavior/dispatch-refusals.yaml`, never here.
 22	 */
 23	class RecentRefusals
 24	{
 25	    private const POLICY_FILE = '/resources/behavior/dispatch-refusals.yaml';
 26	
 27	    /** @var array<string, mixed>|null */
 28	    private static ?array $policy = null;
 29	
 30	    /**
 31	     * The two refusals the gate raises about the *target*: a planet that is online or staging says
 32	     * nothing about the body the fleet would leave from, so an origin is never blamed for them.
 33	     */
 34	    private const TARGET_SIDE_REASONS = [
 35	        AiQueueActionReason::TargetActiveAtDispatch->value,
 36	        AiQueueActionReason::TargetStagingAtDispatch->value,
 37	    ];
 38	
 39	    public function target(int $playerId, int $galaxy, int $system, int $position): bool
 40	    {
 41	        return isset($this->refusedTargets($playerId)["{$galaxy}:{$system}:{$position}"]);
 42	    }
 43	
 44	    /**
 45	     * Whether the window holds a refusal that blamed this origin — for one of $reasons when the caller
 46	     * names them, otherwise for whatever the gate said.
 47	     */
 48	    public function origin(int $playerId, int $planetId, string ...$reasons): bool
 49	    {
 50	        return $this->recent($playerId)
 51	            ->reject($this->targetSide(...))
 52	            ->contains(fn (AiActionReceipt $receipt): bool => ($receipt->result['planet_id'] ?? null) === $planetId
 53	                && ($reasons === [] || in_array($receipt->result['reason'] ?? null, $reasons, true)));
 54	    }
 55	
 56	    /**
 57	     * The coordinates the window's refusals named, keyed "g:s:p": a planner holding a candidate list
 58	     * skips them in one read instead of one query per candidate.
 59	     *
 60	     * @return array<string, true>
 61	     */
 62	    public function refusedTargets(int $playerId): array
 63	    {
 64	        $coordinates = [];
 65	
 66	        foreach ($this->recent($playerId) as $receipt) {
 67	            $galaxy = $receipt->result['decision']['target_galaxy'] ?? null;
 68	            $system = $receipt->result['decision']['target_system'] ?? null;
 69	            $position = $receipt->result['decision']['target_position'] ?? null;
 70	
 71	            if ($galaxy !== null && $system !== null && $position !== null) {
 72	                $coordinates["{$galaxy}:{$system}:{$position}"] = true;
 73	            }
 74	        }
 75	
 76	        return $coordinates;
 77	    }
 78	
 79	    /**
 80	     * The own bodies the window's refusals blamed, keyed by planet id.
 81	     *
 82	     * An origin the gate refused is an origin a player leaves alone for a while, and the reason is not
 83	     * read: the host raises some of them as free text a planner cannot name ("Not enough units on the
 84	     * planet to send the fleet. Units required: colony_ship"), and each one says the dispatch from this
 85	     * body did not happen. Only the target-side reasons are excluded.
 86	     *
 87	     * @return array<int, true>
 88	     */
 89	    public function refusedOrigins(int $playerId): array
 90	    {
 91	        $origins = [];
 92	
 93	        foreach ($this->recent($playerId)->reject($this->targetSide(...)) as $receipt) {
 94	            $planetId = $receipt->result['planet_id'] ?? null;
 95	
 96	            if ($planetId !== null) {
 97	                $origins[(int) $planetId] = true;
 98	            }
 99	        }
100	
101	        return $origins;
102	    }
103	
104	    /** A refusal about the target is no fault of the body the fleet would leave from. */
105	    private function targetSide(AiActionReceipt $receipt): bool
106	    {
107	        return in_array($receipt->result['reason'] ?? null, self::TARGET_SIDE_REASONS, true);
108	    }
109	
110	    /** @return \Illuminate\Support\Collection<int, AiActionReceipt> */
111	    private function recent(int $playerId)
112	    {
113	        return AiActionReceipt::query()
114	            ->where('player_id', $playerId)
115	            ->where('action_type', AiActionType::DispatchFleet->value)
116	            ->where('state', AiReceiptState::Rejected->value)
117	            ->where('created_at', '>', now()->subMinutes($this->coolingMinutes()))
118	            ->get();
119	    }
120	
121	    /**
122	     * The cooling a refusal buys, in minutes, read by name from the behaviour data. Absent data cools
123	     * nothing beyond the moment of the refusal, so a missing file shows up as repeated refusals rather
124	     * than as a silent blackout of every origin.
125	     */
126	    private function coolingMinutes(): int
127	    {
128	        $value = $this->policy()['cooling_minutes'] ?? null;
129	
130	        return is_numeric($value) ? max(0, (int) $value) : 0;
131	    }
132	
133	    /** @return array<string, mixed> */
134	    private function policy(): array
135	    {
136	        if (self::$policy !== null) {
137	            return self::$policy;
138	        }
139	
140	        $path = dirname(__DIR__, 3) . self::POLICY_FILE;
141	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
142	
143	        return self::$policy = is_array($parsed) ? $parsed : [];
144	    }
145	}

