19	/**
20	 * Module-owned adapter over the host's ACS-defend mission: half of each combat hull the source owns
21	 * holds at an ally's planet for an hour. Whether the target is an ally or buddy, and whether ACS is on,
22	 * is the host's gate; the module only keeps half the fleet at home.
23	 */
24	class QueueAiDefendAction implements QueueAiDefend
25	{
26	    private const SPEED = 10.0;
27	
28	    private const HOLDING_HOURS = 1;
29	
30	    public function __construct(
31	        private PlayerGameStateService $playerGameStateService,
32	        private PlanetServiceFactory $planetServiceFactory,
33	    ) {
34	    }
35	
36	    public function handle(int $playerId, int $sourcePlanetId, int $targetPlanetId): AiActionResult
37	    {
38	        if (!Planet::query()->whereKey($sourcePlanetId)->where('user_id', $playerId)->exists()) {
39	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
40	        }
41	
42	        try {
43	            $player = $this->playerGameStateService->advance($playerId, $sourcePlanetId);
44	            if ($player->isBanned()) {
45	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
46	            }
47	            if ($player->isInVacationMode()) {
48	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
49	            }
50	
51	            $source = $this->planetServiceFactory->makeForPlayer($player, $sourcePlanetId, false);
52	            $target = $this->planetServiceFactory->make($targetPlanetId, true);
53	            if ($target === null) {
54	                return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
55	            }
56	
57	            $owned = $source->getShipUnits()->toArray();
58	            $fleet = new UnitCollection();
59	            foreach (ObjectService::getMilitaryShipObjects() as $ship) {
60	                $send = intdiv($owned[$ship->machine_name] ?? 0, 2);
61	                if ($send > 0) {
62	                    $fleet->addUnit($ship, $send);
63	                }
64	            }
65	            if ($fleet->units === []) {
66	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
67	            }
68	
69	            if (!app(FlightFuel::class)->affordable($player, $source, $fleet, $target->getPlanetCoordinates(), self::SPEED, self::HOLDING_HOURS)) {
70	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
71	            }
72	
73	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
74	            $mission = $fleetMissions->createNewFromPlanet(
75	                $source,
76	                $target->getPlanetCoordinates(),
77	                $target->getPlanetType(),
78	                AcsDefendMission::getTypeId(),
79	                $fleet,
80	                new Resources(),
81	                self::SPEED,
82	                self::HOLDING_HOURS,
83	            );
84	
85	            return AiActionResult::queued($mission->id);
86	        } catch (Exception $exception) {
87	            return AiActionResult::rejected($exception->getMessage());
88	        }
89	    }
90	}

