 5	use Modules\AI\Enums\AiObservationKind;
 6	use Modules\AI\Models\AiObservation;
 7	use Modules\AI\Models\AiProfile;
 8	use OGame\Factories\PlayerServiceFactory;
 9	use OGame\Models\BattleReport;
10	use OGame\Models\FleetMission;
