16	/**
17	 * Whether this account should send part of its combat fleet to hold at an ally just seen attacked.
18	 *
19	 * The consumer DEF-010 asked for: the AllyUnderAttack observation names the report, the report names
20	 * the defending co-member. The account helps only a member it still shares an alliance with, only once
21	 * per ally per window, and only from a body that owns combat hulls. The host's ACS-defend gate (buddy
22	 * or alliance, ACS switched on, target exists) is the final word at dispatch.
23	 */
24	class QueueableDefendPlanner
25	{
26	    private const WINDOW_HOURS = 6;
27	
28	    public function __construct(private PlayerServiceFactory $playerServiceFactory)
29	    {
30	    }
31	
32	    public function plan(int $playerId): ?QueueableDefend
33	    {
34	        if (!AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->exists()) {
35	            return null;
36	        }
37	
38	        $myAlliance = User::query()->whereKey($playerId)->value('alliance_id');
39	        if ($myAlliance === null) {
40	            return null;
41	        }
42	
43	        $reportIds = AiObservation::query()
44	            ->where('player_id', $playerId)
45	            ->where('kind', AiObservationKind::AllyUnderAttack)
46	            ->where('observed_at', '>=', now()->subHours(self::WINDOW_HOURS))
47	            ->orderByDesc('observed_at')
48	            ->pluck('source_id');
49	
50	        if ($reportIds->isEmpty()) {
51	            return null;
52	        }
53	
54	        $player = $this->playerServiceFactory->make($playerId, true);
55	        $military = array_map(static fn ($ship) => $ship->machine_name, ObjectService::getMilitaryShipObjects());
56	
57	        foreach ($reportIds as $reportId) {
58	            $allyId = BattleReport::query()->whereKey($reportId)->value('planet_user_id');
59	            if ($allyId === null || User::query()->whereKey($allyId)->value('alliance_id') !== $myAlliance) {
60	                continue;
61	            }
62	
63	            $targetId = Planet::query()->where('user_id', $allyId)->orderBy('id')->value('id');
64	            if ($targetId === null || $this->alreadyHelping($playerId, (int) $targetId)) {
65	                continue;
66	            }
67	
68	            foreach ($player->planets->all() as $source) {
69	                $owned = $source->getShipUnits()->toArray();
70	                foreach ($military as $machine) {
71	                    if (intdiv($owned[$machine] ?? 0, 2) > 0) {
72	                        return app()->makeWith(QueueableDefend::class, [
73	                            'sourcePlanetId' => $source->getPlanetId(),
74	                            'targetPlanetId' => (int) $targetId,
75	                        ]);
76	                    }
77	                }
78	            }
79	        }
80	
81	        return null;
82	    }
83	
84	    /** A defence already sent (and not yet home) to this planet is not sent twice. */
85	    private function alreadyHelping(int $playerId, int $targetPlanetId): bool
86	    {
87	        return FleetMission::query()
88	            ->where('user_id', $playerId)
89	            ->where('mission_type', AcsDefendMission::getTypeId())
90	            ->where('planet_id_to', $targetPlanetId)
91	            ->where('processed', 0)
92	            ->where('canceled', 0)
93	            ->exists();
94	    }
95	}

