 21	/**
 22	 * Answers whether this account can move its fleet off a threatened planet now.
 23	 *
 24	 * A fleetsave is a deployment between the account's own planets: the fleet
 25	 * leaves the planet an inbound hostile can reach and parks on another body the
 26	 * account owns. Both the fleet and the destination are read from the host — the
 27	 * origin is whichever planet carries ships, the destination is any other planet
 28	 * — so the module names neither a ship nor a coordinate.
 29	 */
 30	class QueueableFleetSavePlanner
 31	{
 32	    /** Below this offline gap a save is routine cadence, not an absence (FS-001). */
 33	    private const PROACTIVE_SAVE_MIN_ABSENCE_MINUTES = 120;
 34	
 35	    public function __construct(
 36	        private PlayerServiceFactory $playerServiceFactory,
 37	        private QueueableRecyclePlanner $queueableRecyclePlanner,
 38	        private JumpGateService $jumpGate,
 39	    ) {
 40	    }
 41	
 42	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableFleetSave
 43	    {
 44	        $profile = $this->profile($playerId);
 45	        if ($profile === null || !User::query()->whereKey($playerId)->exists()) {
 46	            return null;
 47	        }
 48	
 49	        $player ??= $this->playerServiceFactory->make($playerId, true);
 50	        $planets = $player->planets->all();
 51	
 52	        // The reactive save (an inbound hostile) is not a matter of taste: a save under
 53	        // attack always wins, so it uses the base band. Aggression only moves the proactive
 54	        // save below, where the account chooses how much fleet it is willing to risk.
 55	        return $this->saveFor($player, $planets, $profile->archetype, 0.5, null, $this->threatenedPlanetIds($player));
 56	    }
 57	
 58	    /**
 59	     * The own planets a hostile fleet is inbound to, from the host's real fleet picture:
 60	     * a mission aimed at one of the account's planets, sent by someone else and still
 61	     * unprocessed. An inbound hostile is owned by the attacker, so the account's own
 62	     * missions can never answer what a reactive save has to move (V6). Which mission
 63	     * types are hostile is the host's own reading — the perception's, not a module list.
 64	     *
 65	     * @return array<int, true>
 66	     */
 67	    private function threatenedPlanetIds(PlayerService $player): array
 68	    {
 69	        $planetIds = [];
 70	        foreach ($player->planets->all() as $planet) {
 71	            $planetIds[] = $planet->getPlanetId();
 72	        }
 73	
 74	        if ($planetIds === []) {
 75	            return [];
 76	        }
 77	
 78	        $threatened = [];
 79	        foreach (FleetMission::query()
 80	            ->whereIn('planet_id_to', $planetIds)
 81	            ->where('user_id', '!=', $player->getId())
 82	            ->where('processed', 0)
 83	            ->where('canceled', 0)
 84	            ->where('mission_type', '!=', EspionageMission::getTypeId())
 85	            ->get(['planet_id_to']) as $mission) {
 86	            $threatened[(int) $mission->planet_id_to] = true;
 87	        }
 88	
 89	        return $threatened;
 90	    }
