 92	    /**
 93	     * The save a player takes before logging off for a real absence, rather
 94	     * than the reactive one an inbound hostile forces (V6). The absence must
 95	     * clear the routine's own inter-session gap; the fleet-value gate lives in
 96	     * saveFor, shared with the reactive plan.
 97	     */
 98	    public function proactivePlan(int $playerId, int $absenceMinutes): ?QueueableFleetSave
 99	    {
100	        if ($absenceMinutes < self::PROACTIVE_SAVE_MIN_ABSENCE_MINUTES) {
101	            return null;
102	        }
103	
104	        $profile = $this->profile($playerId);
105	        if ($profile === null || !User::query()->whereKey($playerId)->exists()) {
106	            return null;
107	        }
108	
109	        $player = $this->playerServiceFactory->make($playerId, true);
110	
111	        return $this->saveFor($player, $player->planets->all(), $profile->archetype, $this->aggression($profile), $absenceMinutes);
112	    }
113	
114	    private function profile(int $playerId): ?AiProfile
115	    {
116	        return AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
117	    }
118	
119	    private function aggression(AiProfile $profile): float
120	    {
121	        return PersonaTaste::fromSeed((int) $profile->random_seed, app(RandomSource::class))->aggression;
122	    }
123	
124	    /**
125	     * @param array<int, PlanetService> $planets
126	     * @param array<int, true> $preferredPlanetIds
127	     */
128	    private function saveFor(PlayerService $player, array $planets, AiArchetype $archetype, float $aggression = 0.5, ?int $absenceMinutes = null, array $preferredPlanetIds = []): ?QueueableFleetSave
129	    {
130	        $origin = $this->origin($planets, $preferredPlanetIds);
131	        if ($origin === null || $this->fleetValue($origin) < $this->exposureBand($archetype, $aggression)) {
132	            return null;
133	        }
134	
135	        // A save moves ships; a planet holding only solar satellites has
136	        // nothing to move and must not plan a flight over an empty fleet.
137	        if (MovableFleet::of($player, $origin->getShipUnits())->units === []) {
138	            return null;
139	        }
140	
141	        // A jump gate moves the whole fleet between two owned moons with no flight time, so
142	        // it beats any flight in exposure: when it is available it is the save (RV-009).
143	        $jump = $this->jumpGateTarget($player, $origin);
144	        if ($jump !== null) {
145	            return app()->makeWith(QueueableFleetSave::class, [
146	                'originPlanetId' => $origin->getPlanetId(),
147	                'destinationPlanetId' => $jump->getPlanetId(),
148	                'missionType' => DeploymentMission::getTypeId(),
149	                'jumpGatePlanetId' => $jump->getPlanetId(),
150	            ]);
151	        }
152	
153	        $ranked = $this->rankedDestinations($player, $planets, $origin);
154	        if ($ranked === []) {
155	            return $this->harvestSaveFallback($player, $origin);
156	        }
157	
158	        $destination = $ranked[0];
159	        $speed = $absenceMinutes === null
160	            ? 1.0
161	            : $this->saveSpeed($player, $origin, $destination, $absenceMinutes);
162	
163	        return app()->makeWith(QueueableFleetSave::class, [
164	            'originPlanetId' => $origin->getPlanetId(),
165	            'destinationPlanetId' => $destination->getPlanetId(),
166	            'missionType' => DeploymentMission::getTypeId(),
167	            'shadowDestinationPlanetId' => $this->shadowDestinationPlanetId($player, $origin, $ranked, $archetype, $aggression),
168	            'speed' => $speed,
169	        ]);
170	    }
171	
172	    /**
173	     * The fastest save speed whose outbound flight still lands at least the
174	     * absence out (FS-012): the fleet stays away the whole absence and is home
175	     * again soon after. The slowest speed stays the floor when no speed can
176	     * reach the absence.
177	     */
178	    private function saveSpeed(PlayerService $player, PlanetService $origin, PlanetService $destination, int $absenceMinutes): float
179	    {
180	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
181	        $absenceSeconds = $absenceMinutes * 60;
182	        $units = MovableFleet::of($player, $origin->getShipUnits());
183	
184	        for ($speed = 10; $speed >= 1; $speed--) {
185	            $duration = $fleetMissions->calculateFleetMissionDuration($origin, $destination->getPlanetCoordinates(), $units, null, (float) $speed);
186	            if ($duration >= $absenceSeconds) {
187	                return (float) $speed;
188	            }
189	        }
190	
191	        return 1.0;
192	    }
193	
194	    /**
195	     * The single-planet fallback (FS-011): with no other own body to deploy to,
196	     * park the fleet on a host debris field via a recycle mission. The field and
197	     * the recycler hull are the recycle planner's own answer; the fallback only
198	     * retargets it as a full-fleet save when that planner's origin is this same
199	     * body, so it never moves a different planet's fleet. ponytail: the recycle
200	     * mission returns the fleet once it arrives, so a long absence is not fully
201	     * covered — the speed/distance sweep is the upgrade path.
202	     */
203	    private function harvestSaveFallback(PlayerService $player, PlanetService $origin): ?QueueableFleetSave
204	    {
205	        $recycle = $this->queueableRecyclePlanner->plan($player->getId());
206	        if ($recycle === null || $recycle->planetId !== $origin->getPlanetId()) {
207	            return null;
208	        }
209	
210	        return app()->makeWith(QueueableFleetSave::class, [
211	            'originPlanetId' => $origin->getPlanetId(),
212	            'destinationPlanetId' => 0,
213	            'missionType' => $recycle->missionType,
214	            'harvestGalaxy' => $recycle->targetGalaxy,
215	            'harvestSystem' => $recycle->targetSystem,
216	            'harvestPosition' => $recycle->targetPosition,
217	        ]);
218	    }
219	
220	    /**
221	     * The second own body a large fleet is split to, or 0 when it is not (V8).
222	     * A split needs two own bodies, a free second slot, both hull roles present,
223	     * and a fleet at least twice what the persona bothers to save, so each wave
224	     * is still worth the trip (FS-009).
225	     *
226	     * @param list<PlanetService> $ranked
227	     */
228	    private function shadowDestinationPlanetId(PlayerService $player, PlanetService $origin, array $ranked, AiArchetype $archetype, float $aggression = 0.5): int
229	    {
230	        if (count($ranked) < 2) {
231	            return 0;
232	        }
233	
234	        if ($player->getFleetSlotsMax() - $player->getFleetSlotsInUse() < 2) {
235	            return 0;
236	        }
237	
238	        if (!$this->hasBothRoles($origin)) {
239	            return 0;
240	        }
241	
242	        if ($this->fleetValue($origin) < 2 * $this->exposureBand($archetype, $aggression)) {
243	            return 0;
244	        }
245	
246	        return $ranked[1]->getPlanetId();
247	    }
248	
249	    /**
250	     * A shadow split moves combat and civil hulls apart, so a fleet with only
251	     * one role has nothing to split (FS-009).
252	     */
253	    private function hasBothRoles(PlanetService $planet): bool
254	    {
255	        $military = array_map(static fn ($object): string => $object->machine_name, ObjectService::getMilitaryShipObjects());
256	        $civil = array_map(static fn ($object): string => $object->machine_name, ObjectService::getCivilShipObjects());
257	
258	        $hasMilitary = false;
259	        $hasCivil = false;
260	        foreach (array_keys($planet->getShipUnits()->toArray()) as $machineName) {
261	            $hasMilitary = $hasMilitary || in_array($machineName, $military, true);
262	            $hasCivil = $hasCivil || in_array($machineName, $civil, true);
263	        }
264	
265	        return $hasMilitary && $hasCivil;
266	    }
267	
268	    /**
269	     * The resources spent on the ships parked here, in the host's raw-price
270	     * unit. Defence is deliberately excluded: a save moves ships, never a
271	     * planet's built defences, so defence weight must not push a turtled
272	     * account into saving a lone cargo (FS-001).
273	     */
274	    private function fleetValue(PlanetService $planet): float
275	    {
276	        $value = 0.0;
277	        foreach ($planet->getShipUnits()->toArray() as $machineName => $amount) {
278	            $value += ObjectService::getObjectRawPrice($machineName)->sum() * $amount;
279	        }
280	
281	        return $value;
282	    }
283	
284	    /**
285	     * The minimum fleet value a persona bothers to save (FS-001). A fleeter
286	     * saves anything real; a trader, miner, turtle or casual player only a
287	     * fleet that is worth the trip. Aggression is risk appetite: a bold account
288	     * tolerates a larger fleet unsaved, a cautious one saves smaller fleets.
289	     * Persona taste over host data, never a gate-1 object list.
290	     */
291	    private function exposureBand(AiArchetype $archetype, float $aggression = 0.5): int
292	    {
293	        $base = match ($archetype) {
294	            AiArchetype::Fleeter, AiArchetype::Raider => 5_000,
295	            AiArchetype::Trader, AiArchetype::Hybrid => 25_000,
296	            AiArchetype::Miner, AiArchetype::Turtle, AiArchetype::Casual => 50_000,
297	        };
298	
299	        // Neutral at aggression 0.5: the base band is what a middling account saves.
300	        // A cautious account (0) saves half as much fleet; a bold one (1) half again as much.
301	        return (int) round($base * (0.5 + $aggression));
302	    }
303	
304	    /**
305	     * The first planet carrying a movable fleet, preferring the planets a hostile
306	     * is inbound to: a reactive save has to move the fleet the attack is aimed
307	     * at, not whichever own body happens to come first in the host's list.
308	     *
309	     * @param array<int, PlanetService> $planets
310	     * @param array<int, true> $preferredPlanetIds
311	     */
312	    private function origin(array $planets, array $preferredPlanetIds = []): ?PlanetService
313	    {
314	        foreach ($planets as $planet) {
315	            if (isset($preferredPlanetIds[$planet->getPlanetId()]) && $planet->getShipUnits()->units !== []) {
316	                return $planet;
317	            }
318	        }
319	
320	        foreach ($planets as $planet) {
321	            if ($planet->getShipUnits()->units !== []) {
322	                return $planet;
323	            }
324	        }
325	
326	        return null;
327	    }
328	
329	    /**
330	     * Own destinations ranked by safety: a body a hostile is already inbound to
331	     * is never a destination (FS-010), the origin's own same-coordinate moon is
332	     * the phalanx-blind hop and ranks first (FS-005), then moons (the phalanx
333	     * cannot see them), then by distance from the origin (a save that flies
334	     * further is harder to phalanx-time) (CRASH-006).
335	     *
336	     * @param array<int, PlanetService> $planets
337	     * @return list<PlanetService>
338	     */
339	    private function rankedDestinations(PlayerService $player, array $planets, PlanetService $origin): array
340	    {
341	        $unsafe = $this->unsafeDestinations($player);
342	
343	        $destinations = array_values(array_filter(
344	            $planets,
345	            static fn (PlanetService $planet): bool => $planet->getPlanetId() !== $origin->getPlanetId()
346	                && !isset($unsafe[$planet->getPlanetId()]),
347	        ));
348	
349	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
350	        usort(
351	            $destinations,
352	            function (PlanetService $left, PlanetService $right) use ($fleetMissions, $origin): int {
353	                $sameCoordinateMoonPreference = $this->isSameCoordinateMoon($origin, $right)
354	                    <=> $this->isSameCoordinateMoon($origin, $left);
355	                if ($sameCoordinateMoonPreference !== 0) {
356	                    return $sameCoordinateMoonPreference;
357	                }
358	
359	                $moonPreference = $this->isMoon($right) <=> $this->isMoon($left);
360	                if ($moonPreference !== 0) {
361	                    return $moonPreference;
362	                }
363	
364	                return $fleetMissions->calculateFleetMissionDistance($origin, $right->getPlanetCoordinates())
365	                    <=> $fleetMissions->calculateFleetMissionDistance($origin, $left->getPlanetCoordinates());
366	            },
367	        );
368	
369	        return $destinations;
370	    }
371	
372	    /**
373	     * The jump-gate save: the origin must be a moon with a gate, the origin must not be on
374	     * cooldown, and at least one other gated moon must be free of both cooldown and an inbound
375	     * hostile (RV-009). The host's own eligibility answers the rest.
376	     */
377	    private function jumpGateTarget(PlayerService $player, PlanetService $origin): ?PlanetService
378	    {
379	        if ($origin->getPlanetType() !== PlanetType::Moon || $origin->getObjectLevel('jump_gate') < 1) {
380	            return null;
381	        }
382	
383	        if ($this->jumpGate->isOnCooldown($origin)) {
384	            return null;
385	        }
386	
387	        $unsafe = $this->unsafeDestinations($player);
388	
389	        foreach ($this->jumpGate->getEligibleTargets($player, $origin) as $target) {
390	            if (!isset($unsafe[$target->getPlanetId()])) {
391	                return $target;
392	            }
393	        }
394	
395	        return null;
396	    }
397	
398	    /**
399	     * The first own body a hostile fleet is already inbound to. Parking the save on one
400	     * of them is worse than holding, so they are not destinations (FS-010). The
401	     * same active-mission source the inbound picture already reads, so this is
402	     * the one authority for "under attack".
403	     *
404	     * @return array<int, true>
405	     */
406	    private function unsafeDestinations(PlayerService $player): array
407	    {
408	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
409	        $unsafe = [];
410	        foreach ($fleetMissions->getActiveFleetMissionsForCurrentPlayer() as $mission) {
411	            if ($mission->user_id !== $player->getId()) {
412	                $unsafe[(int) $mission->planet_id_to] = true;
413	            }
414	        }
415	
416	        return $unsafe;
417	    }
418	
419	    /**
420	     * A moon at the origin's own coordinate: the planet↔moon hop a phalanx
421	     * cannot observe (FS-005). The single safest save, ranked ahead of any
422	     * other moon.
423	     */
424	    private function isSameCoordinateMoon(PlanetService $origin, PlanetService $planet): bool
425	    {
426	        if ($planet->getPlanetType() !== PlanetType::Moon) {
427	            return false;
428	        }
429	
430	        $originCoordinate = $origin->getPlanetCoordinates();
431	        $targetCoordinate = $planet->getPlanetCoordinates();
432	
433	        return $originCoordinate->galaxy === $targetCoordinate->galaxy
434	            && $originCoordinate->system === $targetCoordinate->system
435	            && $originCoordinate->position === $targetCoordinate->position;
436	    }
437	
438	    private function isMoon(PlanetService $planet): bool
439	    {
440	        return $planet->getPlanetType() === PlanetType::Moon;
441	    }
442	
443	    /**
444	     * The parked save this account can bring home, or null when nothing is out.
445	     *
446	     * The host never returns a deployment on its own, so the recall is the other
447	     * half of the save: the account's own in-flight deployment between two of
448	     * its bodies. The ownership check the host's cancel path lacks is the
449	     * `user_id` filter here.
450	     */
451	    public function recallPlan(int $playerId): ?QueueableRecall
452	    {
453	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
454	        if ($profile === null) {
455	            return null;
456	        }
457	
458	        $deployment = FleetMission::query()
459	            ->where('user_id', $playerId)
460	            ->where('mission_type', DeploymentMission::getTypeId())
461	            ->where('canceled', 0)
462	            ->where('processed', 0)
463	            ->where('time_arrival', '>=', now()->timestamp)
464	            ->whereColumn('planet_id_from', '!=', 'planet_id_to')
465	            ->orderBy('time_arrival')
466	            ->first();
467	
468	        if ($deployment === null) {
469	            return null;
470	        }
471	
472	        // The fleet parks half its outbound flight, then returns, with a
473	        // deterministic per-account jitter so a cohort does not all recall on
474	        // the same tick (FS-007).
475	        $flightSeconds = max(0, (int) $deployment->time_arrival - (int) $deployment->time_departure);
476	        $half = (int) round($flightSeconds / 2);
477	        $jitter = (($profile->random_seed % 21) - 10) / 100.0;
478	
479	        return app()->makeWith(QueueableRecall::class, [
480	            'planetId' => (int) $deployment->planet_id_from,
481	            'missionId' => (int) $deployment->id,
482	            'recallAt' => (int) $deployment->time_arrival + $half + (int) round($half * $jitter),
483	        ]);
484	    }
485	}

