 25	/**
 26	 * Module-owned adapter over the host's deployment path, used as a fleetsave.
 27	 *
 28	 * A save is a deployment at the slowest speed between two of the account's own
 29	 * planets: the fleet is away long enough to survive the inbound hostile, and it
 30	 * can be recalled when the account is back. The host deducts the ships
 31	 * atomically and stays the authority on legality.
 32	 */
 33	class QueueAiFleetSaveAction implements QueueAiFleetSave
 34	{
 35	    /** 1.0 is the slowest speed the host accepts (10%), the classic save speed. */
 36	    private const SAVE_SPEED = 1.0;
 37	
 38	    public function __construct(
 39	        private PlayerGameStateService $playerGameStateService,
 40	        private PlanetServiceFactory $planetServiceFactory,
 41	        private JumpGateService $jumpGate,
 42	    ) {
 43	    }
 44	
 45	    public function handle(
 46	        int $playerId,
 47	        int $originPlanetId,
 48	        int $destinationPlanetId,
 49	        int $shadowDestinationPlanetId = 0,
 50	        int $harvestGalaxy = 0,
 51	        int $harvestSystem = 0,
 52	        int $harvestPosition = 0,
 53	        float $speed = 1.0,
 54	        int $jumpGatePlanetId = 0,
 55	    ): AiActionResult {
 56	        if ($jumpGatePlanetId > 0) {
 57	            return $this->jumpSave($playerId, $originPlanetId, $jumpGatePlanetId);
 58	        }
 59	
 60	        if ($harvestPosition > 0) {
 61	            return $this->harvestSave($playerId, $originPlanetId, $harvestGalaxy, $harvestSystem, $harvestPosition);
 62	        }
 63	
 64	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
 65	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 66	        }
 67	        if (!Planet::query()->whereKey($destinationPlanetId)->where('user_id', $playerId)->exists()) {
 68	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 69	        }
 70	
 71	        try {
 72	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
 73	
 74	            if ($player->isBanned()) {
 75	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 76	            }
 77	            if ($player->isInVacationMode()) {
 78	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 79	            }
 80	
 81	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 82	            $destination = $this->planetServiceFactory->makeForPlayer($player, $destinationPlanetId, false);
 83	
 84	            // V8: a large fleet is split across two own bodies so a
 85	            // phalanx-timed crash catches only part (FS-009). The split is
 86	            // decided at planning time; it is re-checked here because the fleet
 87	            // may have changed since.
 88	            if ($shadowDestinationPlanetId > 0
 89	                && Planet::query()->whereKey($shadowDestinationPlanetId)->where('user_id', $playerId)->exists()) {
 90	                $shadow = $this->planetServiceFactory->makeForPlayer($player, $shadowDestinationPlanetId, false);
 91	                [$military, $civil] = $this->splitFleet($player, $origin);
 92	                if ($military->units !== [] && $civil->units !== []) {
 93	                    return $this->dispatchShadowWaves($player, $origin, $destination, $shadow, $military, $civil, $speed);
 94	                }
 95	            }
 96	
 97	            // A save is incomplete unless cargo is loaded too: in-flight
 98	            // resources cannot be raided, and a stripped planet is unprofitable
 99	            // to hit (FS-006). Lift the planet's stock up to what the fleet can
100	            // carry.
101	            $flying = MovableFleet::of($player, $origin->getShipUnits());
102	            if ($flying->units === []) {
103	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
104	            }
105	
106	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
107	
108	            // The host refuses a flight whose fuel is more than the planet holds or the fleet's own
109	            // tanks carry (the two refusals STUCK rows measured on a hundred accounts): a fleet too
110	            // big to fuel sheds its thirstiest hull until it can fly, rather than being offered again.
111	            $flying = $this->trimmedToFuel($player, $origin, $flying, $destination, $speed, $fleetMissions);
112	            if ($flying === null) {
113	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
114	            }
115	
116	            $cargo = $this->liftableStock($player, $origin, $flying, $destination, $speed, $fleetMissions);
117	
118	            $mission = $fleetMissions->createNewFromPlanet(
119	                $origin,
120	                $destination->getPlanetCoordinates(),
121	                $destination->getPlanetType(),
122	                DeploymentMission::getTypeId(),
123	                $flying,
124	                $cargo,
125	                $speed,
126	            );
127	
128	            return AiActionResult::queued($mission->id);
129	        } catch (Exception $exception) {
130	            return AiActionResult::rejected($exception->getMessage());
131	        }
132	    }
133	
134	    /**
135	     * The jump-gate save: the whole transferable fleet moves instantly between two gated moons
136	     * instead of flying. The host's own eligibility is re-checked here — the fleet may have moved
137	     * and the cooldown may have landed since planning (RV-009).
138	     */
139	    private function jumpSave(int $playerId, int $originPlanetId, int $destinationPlanetId): AiActionResult
140	    {
141	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
142	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
143	        }
144	        if (!Planet::query()->whereKey($destinationPlanetId)->where('user_id', $playerId)->exists()) {
145	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
146	        }
147	
148	        try {
149	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
150	
151	            if ($player->isBanned()) {
152	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
153	            }
154	            if ($player->isInVacationMode()) {
155	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
156	            }
157	
158	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
159	            $destination = $this->planetServiceFactory->makeForPlayer($player, $destinationPlanetId, false);
160	
161	            if ($origin->getObjectLevel('jump_gate') < 1
162	                || $destination->getObjectLevel('jump_gate') < 1
163	                || $this->jumpGate->isOnCooldown($origin)
164	                || $this->jumpGate->isOnCooldown($destination)) {
165	                return AiActionResult::rejected(AiQueueActionReason::JumpGateUnavailable);
166	            }
167	
168	            $transferable = array_flip($this->jumpGate->getTransferableShips());
169	            $ships = array_intersect_key($origin->getShipUnits()->toArray(), $transferable);
170	            if ($ships === [] || !$this->jumpGate->transferShips($origin, $destination, $ships)) {
171	                return AiActionResult::rejected(AiQueueActionReason::JumpGateUnavailable);
172	            }
173	
174	            $this->jumpGate->setCooldown($origin, $destination);
175	
176	            return AiActionResult::succeeded(AiQueueActionReason::JumpGateJumped);
177	        } catch (Exception $exception) {
178	            return AiActionResult::rejected($exception->getMessage());
179	        }
180	    }
181	
182	    /**
183	     * The single-planet fallback (FS-011): with no second own body the whole
184	     * fleet rides a recycle mission to a host debris field, so it is in the air
185	     * while the inbound hostile lands. The recycler the mission needs and the
186	     * field are host-read; the slowest speed keeps the fleet away longest. The
187	     * host stays the authority on whether the mission is legal.
188	     */
189	    private function harvestSave(int $playerId, int $originPlanetId, int $galaxy, int $system, int $position): AiActionResult
190	    {
191	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
192	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
193	        }
194	
195	        try {
196	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
197	
198	            if ($player->isBanned()) {
199	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
200	            }
201	            if ($player->isInVacationMode()) {
202	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
203	            }
204	
205	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
206	            $fleet = MovableFleet::of($player, $origin->getShipUnits());
207	            if ($fleet->units === []) {
208	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
209	            }
210	
211	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
212	            $mission = $fleetMissions->createNewFromPlanet(
213	                $origin,
214	                new Coordinate($galaxy, $system, $position),
215	                PlanetType::DebrisField,
216	                RecycleMission::getTypeId(),
217	                $fleet,
218	                new Resources(),
219	                self::SAVE_SPEED,
220	            );
221	
222	            return AiActionResult::queued($mission->id);
223	        } catch (Exception $exception) {
224	            return AiActionResult::rejected($exception->getMessage());
225	        }
226	    }
227	
228	    /**
229	     * Two save waves: the combat hulls to the safer body and the civil hulls,
230	     * which carry the stock, to the other (FS-009). The combat wave leaves
231	     * first, so a refusal on the second still leaves the valuable half parked.
232	     */
233	    private function dispatchShadowWaves(PlayerService $player, PlanetService $origin, PlanetService $destination, PlanetService $shadow, UnitCollection $military, UnitCollection $civil, float $speed): AiActionResult
234	    {
235	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
236	
237	        // A wave with no hulls has no speed to fly at: the host divides by it, so an all-military or
238	        // all-civil fleet sends the one wave it has.
239	        $mission = null;
240	
241	        // Each wave is fuelled on its own: the military wave leaves first and the civil wave is trimmed
242	        // against what that leaves in the tank.
243	        $military = $this->trimmedToFuel($player, $origin, $military, $destination, $speed, $fleetMissions) ?? new UnitCollection();
244	
245	        if ($military->units !== []) {
246	            $mission = $fleetMissions->createNewFromPlanet(
247	                $origin,
248	                $destination->getPlanetCoordinates(),
249	                $destination->getPlanetType(),
250	                DeploymentMission::getTypeId(),
251	                $military,
252	                new Resources(),
253	                $speed,
254	            );
255	        }
256	
257	        $civil = $this->trimmedToFuel($player, $origin, $civil, $shadow, $speed, $fleetMissions) ?? new UnitCollection();
258	
259	        if ($civil->units !== []) {
260	            $civilMission = $fleetMissions->createNewFromPlanet(
261	                $origin,
262	                $shadow->getPlanetCoordinates(),
263	                $shadow->getPlanetType(),
264	                DeploymentMission::getTypeId(),
265	                $civil,
266	                $this->liftableStock($player, $origin, $civil, $shadow, $speed, $fleetMissions),
267	                $speed,
268	            );
269	            $mission ??= $civilMission;
270	        }
271	
272	        if ($mission === null) {
273	            return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
274	        }
275	
276	        return AiActionResult::queued($mission->id);
277	    }
278	
279	    /**
280	     * The origin's hulls separated by the host's own military/civil
281	     * classification (FS-009).
282	     *
283	     * @return array{0: UnitCollection, 1: UnitCollection}
284	     */
285	    private function splitFleet(PlayerService $player, PlanetService $origin): array
286	    {
287	        $militaryNames = array_map(static fn ($object): string => $object->machine_name, ObjectService::getMilitaryShipObjects());
288	        $civilNames = array_map(static fn ($object): string => $object->machine_name, ObjectService::getCivilShipObjects());
289	
290	        $military = new UnitCollection();
291	        $civil = new UnitCollection();
292	
293	        foreach (MovableFleet::of($player, $origin->getShipUnits())->units as $entry) {
294	            $name = $entry->unitObject->machine_name;
295	            if (in_array($name, $militaryNames, true)) {
296	                $military->addUnit($entry->unitObject, $entry->amount);
297	            }
298	
299	            if (in_array($name, $civilNames, true)) {
300	                $civil->addUnit($entry->unitObject, $entry->amount);
301	            }
302	        }
303	
304	        return [$military, $civil];
305	    }
306	
307	    /**
308	     * The planet's stock, scaled to the fleet's cargo hold (FS-006).
309	     */
310	    private function liftableStock(PlayerService $player, PlanetService $origin, UnitCollection $fleet, PlanetService $destination, float $speed, FleetMissionService $fleetMissions): Resources
311	    {
312	        // The flight is paid from the planet's deuterium, so only what is left after the fuel (and at most
313	        // half of it) goes into the hold: a hold that took it all leaves the dispatch short of fuel.
314	        $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination->getPlanetCoordinates(), 0, $speed);
315	        $spare = max(0.0, floor($origin->deuterium()->get()) - ceil($fuel));
316	        $stock = new Resources($origin->metal()->get(), $origin->crystal()->get(), min(floor($origin->deuterium()->get() / 2), $spare));
317	        $capacity = $fleet->getTotalCargoCapacity($player);
318	
319	        if ($stock->sum() <= $capacity) {
320	            return $stock;
321	        }
322	
323	        if ($capacity <= 0) {
324	            return new Resources();
325	        }
326	
327	        // Whole units, rounded down: the host refuses a hold that is full by a fraction.
328	        $share = $capacity / $stock->sum();
329	
330	        return new Resources(
331	            floor($stock->metal->get() * $share),
332	            floor($stock->crystal->get() * $share),
333	            floor($stock->deuterium->get() * $share),
334	        );
335	    }
336	
337	    /**
338	     * The fleet that can be fuelled from this planet and by its own tanks, or null when no hull can.
339	     * The thirstiest hull by fuel per unit is shed first until the flight fits both limits.
340	     */
341	    private function trimmedToFuel(PlayerService $player, PlanetService $origin, UnitCollection $fleet, PlanetService $destination, float $speed, FleetMissionService $fleetMissions): ?UnitCollection
342	    {
343	        $units = [];
344	        foreach ($fleet->units as $entry) {
345	            $units[$entry->unitObject->machine_name] = $entry;
346	        }
347	
348	        while ($units !== []) {
349	            $candidate = new UnitCollection();
350	            foreach ($units as $entry) {
351	                $candidate->addUnit($entry->unitObject, $entry->amount);
352	            }
353	
354	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $candidate, $destination->getPlanetCoordinates(), 0, $speed);
355	            if ($fuel <= floor($origin->deuterium()->get()) && $fuel <= $candidate->getTotalFuelCapacity($player)) {
356	                return $candidate;
357	            }
358	
359	            $thirstiest = null;
360	            $worst = -1.0;
361	            foreach ($units as $name => $entry) {
362	                $single = new UnitCollection();
363	                $single->addUnit($entry->unitObject, $entry->amount);
364	                $perHull = (float) $fleetMissions->calculateConsumption($origin, $single, $destination->getPlanetCoordinates(), 0, $speed);
365	                if ($perHull > $worst) {
366	                    $worst = $perHull;
367	                    $thirstiest = $name;
368	                }
369	            }
370	            unset($units[$thirstiest]);
371	        }
372	
373	        return null;
374	    }
375	}

