 24	/**
 25	 * Module-owned adapter over the host's expedition mission.
 26	 *
 27	 * The slot-16 coordinate, the slot budget and the outcome table are the host's;
 28	 * the module adds the never-fleetsave refusal (EXP-001): a single small
 29	 * disposable hull, never the fleet the account depends on.
 30	 */
 31	class QueueAiExpeditionAction implements QueueAiExpedition
 32	{
 33	    /** The cheapest speed the host accepts (10%), the classic expedition cruise. */
 34	    public const EXPEDITION_SPEED = 1.0;
 35	
 36	    /** The shortest expedition, the classic hourly cadence. */
 37	    public const EXPEDITION_HOLDING_HOURS = 1;
 38	
 39	    public function __construct(
 40	        private PlayerGameStateService $playerGameStateService,
 41	        private PlanetServiceFactory $planetServiceFactory,
 42	    ) {
 43	    }
 44	
 45	    public function handle(int $playerId, int $planetId, int $galaxy, int $system): AiActionResult
 46	    {
 47	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 48	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 49	        }
 50	
 51	        try {
 52	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 53	
 54	            if ($player->isBanned()) {
 55	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 56	            }
 57	            if ($player->isInVacationMode()) {
 58	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 59	            }
 60	
 61	            $origin = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 62	            $fleet = $this->disposableFleet($player, $origin);
 63	            if ($fleet === null) {
 64	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
 65	            }
 66	
 67	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 68	            $destination = new Coordinate($galaxy, $system, 16);
 69	
 70	            // The host refuses a flight whose fuel exceeds the planet's deuterium or the fleet's own
 71	            // tanks. A player sends the cargo hull alone before sending nothing, so the strongest
 72	            // hulls drop out of an expedition the full fleet cannot fuel.
 73	            if (!$this->canFuel($player, $origin, $fleet, $destination, $fleetMissions)) {
 74	                $fleet = $this->cargoOnly($player, $origin);
 75	                if ($fleet === null || !$this->canFuel($player, $origin, $fleet, $destination, $fleetMissions)) {
 76	                    return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 77	                }
 78	            }
 79	
 80	            $mission = $fleetMissions->createNewFromPlanet(
 81	                $origin,
 82	                $destination,
 83	                PlanetType::Planet,
 84	                ExpeditionMission::getTypeId(),
 85	                $fleet,
 86	                new Resources(),
 87	                self::EXPEDITION_SPEED,
 88	                self::EXPEDITION_HOLDING_HOURS,
 89	            );
 90	
 91	            return AiActionResult::queued($mission->id);
 92	        } catch (Exception $exception) {
 93	            return AiActionResult::rejected($exception->getMessage());
 94	        }
 95	    }
 96	
 97	    private function canFuel(PlayerService $player, PlanetService $origin, UnitCollection $fleet, Coordinate $destination, FleetMissionService $fleetMissions): bool
 98	    {
 99	        $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination, self::EXPEDITION_HOLDING_HOURS, self::EXPEDITION_SPEED);
100	
101	        return $fuel <= floor($origin->deuterium()->get()) && $fuel <= $fleet->getTotalFuelCapacity($player);
102	    }
103	
104	    private function cargoOnly(PlayerService $player, PlanetService $origin): ?UnitCollection
105	    {
106	        $cargo = app(QueueableExpeditionPlanner::class)->disposableShip($player, $origin);
107	        if ($cargo === null) {
108	            return null;
109	        }
110	
111	        $fleet = new UnitCollection();
112	        $fleet->addUnit($cargo, 1);
113	
114	        return $fleet;
115	    }
116	
117	    /**
118	     * The expedition fleet: one of each role the body owns — the strongest combat
119	     * hull (survive a pirate), the fastest civil hull (pathfinder), the smallest
120	     * cargo (carry the find) and a probe — never the whole stock (EXP-002). Roles
121	     * the body does not own are simply absent, and each hull flies once.
122	     */
123	    private function disposableFleet(PlayerService $player, PlanetService $origin): ?UnitCollection
124	    {
125	        $planner = app(QueueableExpeditionPlanner::class);
126	
127	        $cargo = $planner->disposableShip($player, $origin);
128	        if ($cargo === null) {
129	            return null;
130	        }
131	
132	        $hulls = [$cargo->machine_name => $cargo];
133	
134	        foreach ([$planner->combatHull($player, $origin), $planner->fastestCivilHull($player, $origin)] as $ship) {
135	            if ($ship !== null) {
136	                $hulls[$ship->machine_name] = $ship;
137	            }
138	        }
139	
140	        $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
141	        if ($origin->getShipUnits()->getAmountByMachineName($probe->machine_name) > 0) {
142	            $hulls[$probe->machine_name] = $probe;
143	        }
144	
145	        $fleet = new UnitCollection();
146	        foreach ($hulls as $ship) {
147	            $fleet->addUnit($ship, 1);
148	        }
149	
150	        return $fleet;
151	    }
152	}

