 29	class QueueAiTransferAction implements QueueAiTransfer
 30	{
 31	    /** 100%: a ferry is wanted at the target, not parked in space. */
 32	    private const TRANSPORT_SPEED = 10.0;
 33	
 34	    public function __construct(
 35	        private PlayerGameStateService $playerGameStateService,
 36	        private PlanetServiceFactory $planetServiceFactory,
 37	        private AllyGiftGuard $giftGuard,
 38	    ) {
 39	    }
