 89	                    return AiActionResult::rejected($refusal);
 90	                }
 91	            }
 92	            $fleet = $this->transportFleet($player, $source, $shipment);
 93	            if ($fleet === null) {
 94	                return AiActionResult::rejected(AiQueueActionReason::NoTransportFleet);
 95	            }
 96	
 97	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
