106	                return AiActionResult::rejected(AiQueueActionReason::NoTransportFleet);
107	            }
108	            if ($fuel > floor($source->deuterium()->get())) {
109	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
