131	    /**
132	     * The flight's fuel rides in the same hold as the cargo, so a shipment that fills the hold
133	     * leaves no room for it and the host refuses with insufficient storage capacity. A player
134	     * loads what is left of the hold after the fuel.
135	     */
136	    private function fittedBesideFuel(PlayerService $player, UnitCollection $fleet, Resources $shipment, int $fuel): Resources
137	    {
138	        $room = max(0, $fleet->getTotalCargoCapacity($player) - $fuel);
139	        $total = $shipment->sum();
140	        if ($total <= $room) {
141	            return $shipment;
142	        }
143	
144	        $share = $room / $total;
145	
146	        return new Resources(
147	            floor($shipment->metal->get() * $share),
148	            floor($shipment->crystal->get() * $share),
149	            floor($shipment->deuterium->get() * $share),
150	        );
151	    }
