 31	class QueueAiRecycleAction implements QueueAiRecycle
 32	{
 33	    /** The cheapest speed the host accepts (10%), a slow harvest run. */
 34	    private const RECYCLE_SPEED = 10.0;
 35	
 36	    public function __construct(
 37	        private PlayerGameStateService $playerGameStateService,
 38	        private PlanetServiceFactory $planetServiceFactory,
 39	    ) {
 40	    }
