 42	    public function handle(int $playerId, int $planetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType): AiActionResult
 43	    {
 44	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 45	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 46	        }
 47	
 48	        try {
 49	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 50	
 51	            if ($player->isBanned()) {
 52	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 53	            }
 54	            if ($player->isInVacationMode()) {
 55	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 56	            }
 57	
 58	            $origin = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 59	            $fleet = $this->harvestFleet($player, $origin, $targetGalaxy, $targetSystem, $targetPosition);
 60	            if ($fleet === null) {
 61	                return $this->queueHarvestHull($player, $origin, $targetGalaxy, $targetSystem, $targetPosition);
 62	            }
 63	
 64	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 65	            $destination = new Coordinate($targetGalaxy, $targetSystem, $targetPosition);
 66	
 67	            // The host refuses a harvest the origin cannot fuel, so it is refused here by name.
 68	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination, 0, self::RECYCLE_SPEED);
 69	            if ($fuel > floor($origin->deuterium()->get()) || $fuel > $fleet->getTotalFuelCapacity($player)) {
 70	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 71	            }
 72	
 73	            $mission = $fleetMissions->createNewFromPlanet(
 74	                $origin,
 75	                $destination,
 76	                PlanetType::from($targetType),
 77	                RecycleMission::getTypeId(),
 78	                $fleet,
 79	                new Resources(),
 80	                self::RECYCLE_SPEED,
 81	            );
 82	
 83	            return AiActionResult::queued($mission->id);
 84	        } catch (Exception $exception) {
 85	            return AiActionResult::rejected($exception->getMessage());
 86	        }
 87	    }
