 89	    /**
 90	     * Enough harvest hulls to carry the field, capped by what the body holds.
 91	     *
 92	     * The hull is the one the host's RecycleMission requires for the slot and its
 93	     * capacity is the host's own figure, so a mod that changes either changes the
 94	     * count with no module edit. At least one hull flies for a field still worth
 95	     * a trip.
 96	     */
 97	    private function harvestFleet(PlayerService $player, PlanetService $origin, int $galaxy, int $system, int $position): ?UnitCollection
 98	    {
 99	        $ship = ObjectService::getShipObjectByMachineName(RecycleMission::getHarvesterMachineNameForPosition($position));
100	        $available = $origin->getShipUnits()->getAmountByMachineName($ship->machine_name);
101	        if ($available <= 0) {
102	            return null;
103	        }
104	
105	        $capacity = $ship->properties->capacity->calculate($player)->totalValue;
106	        $needed = (int) ceil($this->fieldMass($galaxy, $system, $position) / max(1, $capacity));
107	        $count = max(1, min($available, $needed));
108	
109	        $fleet = new UnitCollection();
110	        $fleet->addUnit($ship, $count);
111	
112	        return $fleet;
113	    }
114	
115	    /**
116	     * With no harvest hull on hand the intent builds the hull that collects the field
117	     * instead of failing, so a decided recycle eventually flies. The hull is the one the
118	     * host's RecycleMission requires for the slot, and the count is what the field needs:
119	     * a build is only ordered for a field that is still there.
120	     */
121	    private function queueHarvestHull(PlayerService $player, PlanetService $origin, int $galaxy, int $system, int $position): AiActionResult
122	    {
123	        $mass = $this->fieldMass($galaxy, $system, $position);
124	        if ($mass <= 0) {
