126	        }
127	
128	        $ship = ObjectService::getShipObjectByMachineName(RecycleMission::getHarvesterMachineNameForPosition($position));
129	        $capacity = $ship->properties->capacity->calculate($player)->totalValue;
130	        $count = max(1, (int) ceil($mass / max(1, $capacity)));
131	
132	        app(UnitQueueService::class)->add($origin, $ship->id, $count);
133	
134	        return AiActionResult::queued($ship->id);
135	    }
