118	    /**
119	     * Create a user and authenticate without HTTP round-trips.
120	     */
121	    protected function createAndLoginUser(): void
122	    {
123	        // Seed the planet allocator so the homeworld lands at a fixed, collision-safe
124	        // system far from both the seeded Legor admin account (1:1:2) and any planets
125	        // leaked by non-transactional tests (Admin/Ban/Buddy populate systems 1..N).
126	        // Without this, position-based colonisation tests collide with Legor's 1:1:2, and
127	        // the distance between the two home planets drifts (raising deuterium fuel past
128	        // the budget in FleetDispatchLargeResourcesTest).
129	        resolve(SettingsService::class)->set('last_assigned_system', 400);
130	
131	        $user = $this->createUser();
132	
133	        $this->actingAs($user);
134	
135	        $this->currentUserId = $user->id;
136	        $this->currentUsername = $user->username;
137	
138	        // Wire up planet services from the real factory.
139	        $playerServiceFactory = resolve(PlayerServiceFactory::class);
140	        $playerService = $playerServiceFactory->make($user->id, true);
141	
142	        $this->planetService = $playerService->planets->current();
143	        $this->currentPlanetId = $this->planetService->getPlanetId();
144	
145	        // Reproduce the page-load side effects real registration triggers.
146	        $playerService->update();
147	        $this->planetService->update();
